import React from 'react';
import './Hero.css';

export const Hero = () => {
  return (
    <section className="hero-section">

      {/* Layer 0 — Sky background */}
      <img
        src={process.env.PUBLIC_URL + '/bg%20hero.webp'}
        alt=""
        className="hero-bg"
        aria-hidden="true"
      />

      {/* Layer 2 — Text & CTA */}
      <div className="nl-hero-content">
        <div className="nl-badge">
          <span className="nl-badge-dot" aria-hidden="true" />
          <span className="nl-badge-text">Beta Testing is Now Live</span>
        </div>

        <h1 className="nl-hero-heading">
          The intelligent travel companion<br />
          for <em>every journey you take.</em>
        </h1>
        <p className="nl-hero-subtitle">
          Your journey, our priority. Powered by AI, tailored for you.
        </p>

        <div className="nl-cta-row">
          <button
            id="nl-get-started"
            className="nl-btn-primary nl-btn-magnetic"
            onMouseMove={(e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              const x = e.clientX - rect.left - rect.width / 2;
              const y = e.clientY - rect.top - rect.height / 2;
              e.currentTarget.style.transform = `translate(${x * 0.15}px, ${y * 0.15}px)`;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = `translate(0, 0)`;
            }}
          >
            <span>Try the Beta</span>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ marginLeft: '8px' }}>
              <line x1="5" y1="12" x2="19" y2="12"></line>
              <polyline points="12 5 19 12 12 19"></polyline>
            </svg>
          </button>

          <button
            id="nl-learn-more"
            className="nl-btn-secondary nl-btn-magnetic"
            onMouseMove={(e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              const x = e.clientX - rect.left - rect.width / 2;
              const y = e.clientY - rect.top - rect.height / 2;
              e.currentTarget.style.transform = `translate(${x * 0.15}px, ${y * 0.15}px)`;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = `translate(0, 0)`;
            }}
          >
            See how it works
          </button>
        </div>
      </div>

      {/* Layer 3 — Dashboard card (sits above text in z-order, below hills) */}
      <div className="hero-dashboard-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/hero%20bg%20new.webp'}
          alt="Dishastra app dashboard"
          className="hero-dashboard"
        />
      </div>

      {/* Layer 4 — Hills foreground (overlaps bottom of dashboard) */}
      <div className="hero-hills-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/image.webp'}
          alt=""
          className="hero-hills"
          aria-hidden="true"
        />
      </div>

    </section>
  );
};
